/// <summary>
/// PaffH 17.10.24
/// </summary>
/// <param name = "_parentRecId">NDXProdIdentControlPanelParent</param>
/// <returns>parentrecord exist</returns>
public static boolean exist(RefRecId _parentRecId)
{
    return _parentRecId && (select firstonly RecId from NDXProdIdentControlPanelLine
        where NDXProdIdentControlPanelLine.NDXProdIdentControlPanelParent == _parentRecId).RecId != 0;
}

/// <summary>
/// PaffH 16.10.24
/// </summary>
/// <param name = "_parentRecId">Parent recId NDXProdIdentControlPanel</param>
/// <param name = "_ListNDXProdIdentControlPanel">List of NDXProdIdentControlPanel</param>
public static void fillFromRecordList(RefRecId _parentRecId, List _listNDXProdIdentControlPanel)
{
    boolean first = true;
    NDXProdIdentControlPanel nDXProdIdentControlPanel;
    Query q = new Query();
    QueryBuildDataSource qbds = q.addDataSource(tableNum(NDXProdIdentControlPanelLine));
    qbds.update(true);
    QueryBuildRange qbr = qbds.addRange(fieldNum(NDXProdIdentControlPanelLine, RecId));

    str qbrValue = strFmt('(%1.%2 == %3)', qbds.name(), fieldStr(NDXProdIdentControlPanelLine, NDXProdIdentControlPanelParent), _parentRecId);
    NDXProdIdentControlPanelLine nDXProdIdentControlPanelLine;
    NDXProdIdentControlPanelLine nDXProdIdentControlPanelLineFound;
    ListEnumerator enum = _listNDXProdIdentControlPanel.getEnumerator();
    while (enum.moveNext())
    {
        nDXProdIdentControlPanel = enum.current();
        nDXProdIdentControlPanelLineFound = NDXProdIdentControlPanelLine::findOrCreate(_parentRecId, nDXProdIdentControlPanel.RecId, true);
        qbrValue += ' && ';
        if (first)
        {
            qbrValue += '(';
        }
        qbrValue += strFmt('(%1.%2 != %3)', qbds.name(), fieldStr(NDXProdIdentControlPanelLine, NDXProdIdentControlPanel), nDXProdIdentControlPanel.RecId);
        first = false;
    }
    if (!first)
    {
        qbrValue += ')';
        qbr.value(qbrValue);
        // delete invalid records
        ttsbegin;
        QueryRun qr = new QueryRun(q);
        while (qr.next())
        {
            nDXProdIdentControlPanelLine = qr.get(tableNum(NDXProdIdentControlPanelLine));
            nDXProdIdentControlPanelLine.delete();
        }
        ttscommit;
    }

}

/// <summary>
/// PaffH 16.10.24
/// </summary>
/// <param name = "_parent">RefRecId</param>
/// <param name = "_line">RefRecId</param>
/// <param name = "_update">boolean</param>
/// <returns>NDXProdIdentControlPanelLine</returns>
public static NDXProdIdentControlPanelLine find(RefRecId _parent, RefRecId _line, boolean _update)
{
    NDXProdIdentControlPanelLine nDXProdIdentControlPanelLine;
    nDXProdIdentControlPanelLine.selectForUpdate(_update);
    select firstonly nDXProdIdentControlPanelLine
        where nDXProdIdentControlPanelLine.NDXProdIdentControlPanelParent == _parent
        && nDXProdIdentControlPanelLine.NDXProdIdentControlPanel == _line;

    return nDXProdIdentControlPanelLine;
}

/// <summary>
/// PaffH 16.10.24
/// </summary>
/// <param name = "_parent">RefRecId</param>
/// <param name = "_line">RefRecId</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXProdIdentControlPanelLine</returns>
public static NDXProdIdentControlPanelLine findOrCreate(RefRecId _parent, RefRecId _line, boolean _insert = false)
{
    NDXProdIdentControlPanelLine nDXProdIdentControlPanelLine = NDXProdIdentControlPanelLine::find(_parent, _line, true);
    if (!nDXProdIdentControlPanelLine)
    {
        nDXProdIdentControlPanelLine.NDXProdIdentControlPanelParent = _parent;
        nDXProdIdentControlPanelLine.NDXProdIdentControlPanel = _line;
        if (_insert)
        {
            nDXProdIdentControlPanelLine.insert();
        }
    }
    return nDXProdIdentControlPanelLine;
}
